<div class="page-heading"><div><p class="eyebrow">内容</p><h1>单页管理</h1></div><?php if ($can['content.manage'] ?? false): ?><a class="button" href="/admin/pages/new">新建单页</a><?php endif; ?></div>
<div class="panel table-wrap"><table><thead><tr><th>标题</th><th>别名</th><th>状态</th><th>排序</th><th>操作</th></tr></thead><tbody>
<?php foreach ($pages as $page): ?><tr><td><?= \FangdaysCMS\Cms\View::e($page['title']) ?></td><td><?= \FangdaysCMS\Cms\View::e($page['slug']) ?></td><td><?= $page['status'] === 'published' ? '已发布' : '草稿' ?></td><td><?= (int) $page['menu_order'] ?></td><td class="actions"><?php if ($page['status'] === 'published'): ?><a href="/page/<?= \FangdaysCMS\Cms\View::e($page['slug']) ?>" target="_blank" rel="noopener">查看</a><?php endif; ?><?php if ($can['content.manage'] ?? false): ?><a href="/admin/pages/<?= (int) $page['id'] ?>/edit">编辑</a><form class="inline-form" method="post" action="/admin/pages/<?= (int) $page['id'] ?>/delete" onsubmit="return confirm('确定删除此单页？')"><?= \FangdaysCMS\Cms\View::csrf() ?><button class="link-button danger" type="submit">删除</button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (! $pages): ?><tr><td colspan="5" class="muted">尚未创建单页。</td></tr><?php endif; ?>
</tbody></table></div>
